/**
 * Guard for #8699: apps/marketing/public/metrics.json drives the homepage
 * "Snapshot from <date>" label, the /metrics history and /ai-health. It was
 * only regenerated by the weekly pr-metrics.yml, so every surface lagged up
 * to a week behind the daily ACMM audit that feeds it. The daily workflow
 * must regenerate it and ship it in the same automation PR.
 */

import { describe, it, expect } from "vitest";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { loadWorkflow } from "../lib/workflow.mjs";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, "../..");
const wf = loadWorkflow(resolve(ROOT, ".github/workflows/acmm-regression.yml"));
const job = Object.values(wf.jobs)[0];

describe("acmm-regression regenerates the marketing metrics snapshot (#8699)", () => {
  const steps = job.steps;
  const genIdx = steps.findIndex((s) =>
    (s.run ?? "").includes("node scripts/generate-metrics-json.mjs")
  );
  const prIdx = steps.findIndex((s) => s.id === "create-pr");

  it("runs generate-metrics-json after the audit refreshes state.json", () => {
    const auditIdx = steps.findIndex((s) =>
      (s.run ?? "").includes("plugins/acmm/scripts/audit.js")
    );
    expect(genIdx).toBeGreaterThan(auditIdx);
  });

  it("generates before the PR step", () => {
    expect(genIdx).toBeGreaterThan(-1);
    expect(genIdx).toBeLessThan(prIdx);
  });

  it("commits metrics.json in the automation PR", () => {
    expect(steps[prIdx].with["add-paths"]).toContain("apps/marketing/public/metrics.json");
  });
});
